    "content": "冯骥才 光明日报记者 李韵摄 记者又一次走进天津大学冯骥才文学艺术研究院内的一间工作室—— 屋里摆放了大量的书籍和各种艺术品，把面积不算小的办公室“塞”得有点局促。 这是冯骥才平时工作的地方。 “欢迎欢迎！”洪亮的嗓音伴着伸过来的大手，冯骥才开始又一次接受记者的采访。眼前的老人，身材高大。毕竟是84岁的人了，尽管笑容仍然灿烂，笑声依然爽朗，眼睛依然熠熠有神，但脸上的疲倦还是清晰可见。记者不由心生歉意。冯骥才似乎看懂了记者心思，笑道：“再累，光明日报的采访还是要做的。” “我的人生，驾驶着‘四驾马车’：文学创作、绘画…"
