    "title": "支持率创新低，韩总统李在明向国民致歉：不连任、不参战中东",
    "link": "https://m.thepaper.cn/detail/34099160",
    "pub_date": "2026-09-19 07:16:00",
    "author": "澎湃新闻记者 杨一",
    "description": "据中国新闻网报道， 民调机构韩国盖洛普18日发布的一项民调结果显示，总统李在明施政好评率跌至37%，连续四周创新低。李在明在18日召开的记者会上对自身支持率持续下降的问题表示，所有原因都在于自身能力不足。李在明称：“我不够细致、缺乏沟通，部分国民受政策负面影响而对政府心生不满，但我却未能正视类似理所当然的反应，导致国民认为没有被切实得到尊重，而致使支持率下降。”",
