    "content": "新华社华盛顿9月18日电 美国总统特朗普18日在社交媒体发布消息称，美国已与丹麦及其自治领地格陵兰岛达成一项协议，“赋予美国对格陵兰岛安全及其他需求的永久控制权”。 特朗普说，美国代表与丹麦和格陵兰岛方面进行了磋商，确保美国能在格陵兰岛采取必要行动，以保障格陵兰岛和美国的安全。 他还说，今后如无美方书面批准，美国的对手将不能在格陵兰岛建立基地、部署军事力量或进行敏感投资。而美方将立即着手在格陵兰岛合适区域展开军事部署。 丹麦首相府同日发布消息说，格陵兰岛、丹麦和美国预计将于下周签署这份协议，“以加强北极及北大西洋地…"
