    "content": "新华社赫尔辛基9月18日电（记者朱昊晨 褚怡）斯德哥尔摩消息：瑞典议会议长安德烈亚斯·诺伦18日宣布，授权议会第一大党社会民主党党首、前首相玛格达莱娜·安德松尝试组建新一届政府。 安德松当天早些时候对瑞典媒体表示，她已向议长表明愿意尝试组建新政府；如果获得尝试组阁的授权，她将与多个政党领导人展开广泛磋商。 瑞典选举委员会17日公布的议会选举计票结果显示，包括社会民主党在内的反对党阵营赢得349个议席中的176个，取得议会多数。 瑞典首相、温和党党首乌尔夫·克里斯特松17日宣布辞职。议长随后启动新政府组建程序。在新政…"
