    "description": "新华社上海9月18日电（记者陈潇雨）上海市十六届人大常委会第三十四次会议18日表决通过关于修改《上海市住宅物业管理规定》的决定，为推动实现社区高效能治理、物业行业高质量发展、人民群众高品质生活提供有力法治保障。 为充分发挥业委会在住宅小区物业治理中的重要作用，决定明确街镇及时组建筹备组或换届改选小组、业主大会会议可以通过互联网方式进行、业主大会可以选举业委会候补委员；明确居（村）委会可以选派社区工作者为业委会提供专业化支持和帮助；明确业…",
    "content": "新华社上海9月18日电（记者陈潇雨）上海市十六届人大常委会第三十四次会议18日表决通过关于修改《上海市住宅物业管理规定》的决定，为推动实现社区高效能治理、物业行业高质量发展、人民群众高品质生活提供有力法治保障。 为充分发挥业委会在住宅小区物业治理中的重要作用，决定明确街镇及时组建筹备组或换届改选小组、业主大会会议可以通过互联网方式进行、业主大会可以选举业委会候补委员；明确居（村）委会可以选派社区工作者为业委会提供专业化支持和帮助；明确业委会委员禁止行为及相应的法律责任。 针对因业委会缺位导致物业治理失灵失效情形，决…"
