    "content": "新华社北京9月18日电（记者阳娜）为培育词元经济发展新增量，18日发布的《北京市加快词元经济发展的行动方案（2026—2028年）》明确，北京将强化生产端供给，高标准建设词元工厂，推动词元分发平台纳入新型基础设施布局，培育消费端生态，拓展词元应用场景。 词元是大模型处理信息的基本计量单位。行动方案从词元工厂建设、关键核心技术攻关、词元质量评测、词元分发平台、智能体培育与应用、智能体核心软件生态、海外服务能力、数据本体技术、词元工程师培训等方面提出10条举措。 根据行动方案，北京将高标准建设词元工厂，制定北京市词元工…"
