    "content": "新华社莫斯科9月18日电（记者黄河）俄罗斯外交部18日发表声明说，为回应欧盟此前批准针对俄罗斯的第21轮制裁措施，俄方大幅扩充了禁止入境俄罗斯的欧盟人员名单。 声明说，今年7月23日，欧盟批准了旨在损害俄罗斯利益的第21轮制裁措施。作为回应，俄方根据国内法律规定，大幅扩充了禁止入境俄罗斯的欧盟人员名单，其中包括参与决定向乌克兰提供军事援助的人员；从事旨在破坏俄联邦领土完整活动的人员；负责实施反俄制裁、损害俄与第三国关系或阻碍俄海上航行的人员等。 声明还说，对欧洲国家中持反俄立场的有关人士，以及投票支持反俄决议和法案…"
