    "content": "新华社香港9月18日电 题：定发展航向 启兴港新程——香港特区行政长官李家超解读首个五年规划 新华社记者郭鑫、刘欢 香港特别行政区第一个五年规划16日正式公布。在香港特区行政长官李家超看来，2026年是国家“十五五”规划开局之年，香港首份五年规划同步启程，“这不是时间上的巧合，而是特区主动抢抓机遇的必然选择”。 这份约6万字、涵盖105项核心发展指标的规划，是香港回归祖国以来首份覆盖经济社会全领域的系统性中长期发展蓝图，与同日发布的2026年施政报告共同搭建起“长远谋篇、年度落地”的治理新框架。 17日，李家超接受…"
