    "content": "图为9月12日，新书发布会现场。左三为作者黄鸿玺。主办方供图 一场新书发布会9月12日在北京三联书店举行。发布会的主角、新书作者黄鸿玺的人生颇富传奇色彩：生于中国台湾，长于加拿大。年少时，受李小龙主演的华人电影启发，黄鸿玺开始习武。大学毕业后，他回到台湾，加入云门舞集担任武术指导，随后利用云门“流浪者计划”资助，走访中国大陆北方多省市寻访隐于乡野的武术高手。2011年，黄鸿玺在北京胡同深处创办“夜奔北京”客栈，十年间，来自世界各地的武者相聚于此，以武会友。《夜奔：客栈里的武林》记录的就是发生在四合院里的故事。"
