    "description": "新华社北京9月18日电（记者古一平）记者18日从农业农村部获悉，农业农村部、工业和信息化部近日印发《全国农业机械化发展“十五五”规划》，明确到2030年，我国农作物耕种收综合机械化率超过80%，小麦、水稻、玉米三大主粮实现更高水平机械化。 规划提出，到2030年，农业机械化高质量发展取得显著成效。平原地区农作物机械化水平质效进一步提升，丘陵山区农作物耕种收综合机械化率力争提高到75%以上。畜牧水产养殖、农产品初加工机械化加快发展。人工智…",
    "content": "新华社北京9月18日电（记者古一平）记者18日从农业农村部获悉，农业农村部、工业和信息化部近日印发《全国农业机械化发展“十五五”规划》，明确到2030年，我国农作物耕种收综合机械化率超过80%，小麦、水稻、玉米三大主粮实现更高水平机械化。 规划提出，到2030年，农业机械化高质量发展取得显著成效。平原地区农作物机械化水平质效进一步提升，丘陵山区农作物耕种收综合机械化率力争提高到75%以上。畜牧水产养殖、农产品初加工机械化加快发展。人工智能、新能源等新技术新装备在农业机械化领域广泛应用。农机作业社会化服务能力大幅提高…"
