    "content": "新华社北京9月18日电 记者18日从生态环境部获悉，生态环境部、国家市场监督管理总局联合印发文件，推进机动车排放检验机构监管改革，提升排放检验质量，为完善机动车排放检验机构监管体系、推动检验质量全面提升和空气质量持续改善提供政策指导。 这份文件立足机动车排放检验领域现状，聚焦机动车排放检验机构设备管理、检验操作、日常运维、人员技能等薄弱环节，建立健全权责清晰、运行规范、全程可溯、常态监管的全过程管理体系。 文件指导机动车排放检验机构按照生态环境法典要求落实主体责任，同时统筹政府监管、行业自律、社会监督等多元力量共治…"
