    "description": "新华社北京9月18日电 丹麦18日在北海启用“绿沙”碳捕集与封存设施，将二氧化碳注入海底储层。作为欧盟境内首个规模化二氧化碳封存项目，“绿沙”第一阶段预计每年可封存40万吨二氧化碳。 牵头该项目的英力士集团在官网发布声明说，二氧化碳将被封存于距丹麦西海岸约250公里的废弃油田尼尼韦斯特下方海底，深达海床之下约1800米。在第一阶段商业运营中，“绿沙”项目每年最多可封存40万吨二氧化碳。随着需求增长，封存能力计划到2030年扩大至每年40…",
    "content": "新华社北京9月18日电 丹麦18日在北海启用“绿沙”碳捕集与封存设施，将二氧化碳注入海底储层。作为欧盟境内首个规模化二氧化碳封存项目，“绿沙”第一阶段预计每年可封存40万吨二氧化碳。 牵头该项目的英力士集团在官网发布声明说，二氧化碳将被封存于距丹麦西海岸约250公里的废弃油田尼尼韦斯特下方海底，深达海床之下约1800米。在第一阶段商业运营中，“绿沙”项目每年最多可封存40万吨二氧化碳。随着需求增长，封存能力计划到2030年扩大至每年400万至800万吨。 据法新社报道，这些二氧化碳主要来自丹麦境内的生物甲烷工厂，经…"
