    "pub_date": "2026-09-18 22:47:49",
    "author": "",
    "description": "中新网兰州9月18日电 (高文)九月的甘肃陇南，秋雨初歇。武都区坪垭藏族乡的安置区如同一朵八瓣莲花铺展在白龙江畔。2016年，甘肃省“十三五”时期整乡易地扶贫搬迁项目在此启动，2018年10月，1236户5731名藏乡儿女从海拔1100米至3200米的“九沟八梁”上搬到了这里。",
    "content": "中新网兰州9月18日电 (高文)九月的甘肃陇南，秋雨初歇。武都区坪垭藏族乡的安置区如同一朵八瓣莲花铺展在白龙江畔。2016年，甘肃省“十三五”时期整乡易地扶贫搬迁项目在此启动，2018年10月，1236户5731名藏乡儿女从海拔1100米至3200米的“九沟八梁”上搬到了这里。"
