    "description": "\"国家体育总局相关部门负责人表示，坚决抵制针对运动员、教练员等体育工作者的网暴行为。\" 近日，公安部公布体育领域网络暴力违法犯罪典型案例，依法对涉案人员作出处理，向全社会释放依法严打网络暴力行为的鲜明态度和明确信号。国家体育总局相关部门负责人表示，坚决抵制针对运动员、教练员等体育工作者的网暴行为。 该负责人表示，广大体育爱好者是体育事业的建设者和参与者，为体育事业改革发展提出了很多建设性的意见建议。网络不是法外之地，请体育爱好者依法依规…",
    "content": "\"国家体育总局相关部门负责人表示，坚决抵制针对运动员、教练员等体育工作者的网暴行为。\" 近日，公安部公布体育领域网络暴力违法犯罪典型案例，依法对涉案人员作出处理，向全社会释放依法严打网络暴力行为的鲜明态度和明确信号。国家体育总局相关部门负责人表示，坚决抵制针对运动员、教练员等体育工作者的网暴行为。 该负责人表示，广大体育爱好者是体育事业的建设者和参与者，为体育事业改革发展提出了很多建设性的意见建议。网络不是法外之地，请体育爱好者依法依规表达观点、传递热爱。体育总局将积极会同相关部门加强体育领域反网络暴力工作，坚决抵…"
