    "content": "新华社莫斯科9月18日电（记者赵冰）俄罗斯外交部发言人扎哈罗娃18日在俄外交部官网发表评论说，俄方要求日方撤出在日本部署的美国“堤丰”中程导弹系统。 扎哈罗娃表示，俄方已于3日就在日本部署“堤丰”中导系统向日本发出抗议照会。无论日方以何种借口，无论部署期限与方式如何，均不得在本国领土前沿部署该导弹系统。此外，日本政府还必须全面承认二战结果，包括涉南千岛群岛（日本称北方四岛）的领土归属问题，并放弃其再军事化政策。 评论还提到，俄外交部副部长鲁坚科16日在莫斯科会见日本驻俄大使武藤显时，呼吁日本认真对待俄方此前递交的这…"
