    "content": "新华社北京9月18日电 据韩国媒体报道，由于食品价格普遍上涨，韩国消费者更加精打细算，购买水果和蔬菜等食品时倾向于购买切块的小份装。 韩国《中央日报》18日的一篇报道记录了这样一个场景：周四下午，金秀敏（音译）站在首尔西部一家超市的货架前，犹豫着究竟是买一整个卷心菜，还是买切开的四分之一个。尽管整个购买的单位价格更便宜，但小份菜总价更低。她纠结一番，最后还是选择了小份菜，“省下的钱可以买点别的”。 2022年7月5日，韩国首尔市民在一家超市购物。新华社记者王益亮摄 报道说，官方统计数据显示，8月消费者价格指数同比上…"
