    "content": "新华社南宁9月18日电 题：一河贯山海——平陆运河书写西南向海新篇章 新华社记者段羡菊、向志强、陈露缘 金秋九月，西江奔流。 9月16日，世纪工程平陆运河建成通航。这个江铁海多式联运的重大基础设施、西部陆海新通道的骨干工程，迎来历史性时刻。 在习近平总书记“高标准、高质量建设平陆运河”的嘱托引领下，从中央到地方，从设计论证、科技攻关到建设运营，这条历经4年奋战、全长134.2公里的运河惊艳问世，将有力支持广西向海图强、开放发展，为中国和东盟加强互联互通、高质量共建“一带一路”注入新动能。 百年夙愿圆梦江海通途 平陆…"
