    "content": "新华社加德满都9月18日电（记者张平）尼泊尔科学、技术和创新部部长马哈比尔·普恩18日在首都加德满都表示，尼泊尔政府高度肯定中国隧道救援专家的工作。 普恩当天会见中国驻尼泊尔大使张茂明和中国隧道救援专家时表示，感谢中国政府和人民为尼泊尔应对严重泥石流灾害提供鼎力支持和无私帮助，尼方愿同中方加强在防灾减灾和灾后重建领域的合作，不断增进尼中两国人民福祉。 张茂明表示，中方将同尼方守望相助、共克时艰，继续为尼方处置严重泥石流灾害和灾后重建提供帮助。 普恩还与张茂明签署了中国援尼隧道救援物资交接证书。 应尼泊尔政府请求，中…"
