    "content": "新华社日本名古屋9月18日电（记者曹奕博、李博闻）中国男篮18日在爱知·名古屋亚运会男篮半决赛中以77:97不敌日本队，继2023年杭州亚运会后，再次无缘决赛。 四分之一决赛锋线告急的中国男篮此役迎来赵嘉义和李弘权伤愈复出，朱俊龙则继续因伤缺阵。东道主日本队虽然未派出八村塁、河村勇辉等此前参加世预赛的主力球员，但本土联赛明星后卫黑川虎彻和归化中锋柯克在本届赛事中表现亮眼。 开场后，中国男篮迟迟未能进入状态，外线手感尤其不佳，前两节三分球12投仅3中。主场作战的日本队则打得十分积极，前锋金近廉首节里突外投得到9分，柯…"
