    "content": "新华社日本名古屋9月18日电（记者刘杨、高路）爱知·名古屋亚运会女子排球小组赛18日结束六场争夺。中国女排直落三局完胜哈萨克斯坦队，以B组头名晋级八强。根据赛程，中国队将在20日的四分之一决赛中对阵越南队。 中国队和哈萨克斯坦队均已提前晋级，此役将决定小组最终排名。比赛开始后，哈萨克斯坦队依靠主动进攻与发球冲击率先发力。中国女排迅速调整状态，稳住一传防线，同时通过多点进攻逐步打开局面，以25:18先拔头筹。 中国队在次局彻底掌控节奏，进攻端快攻、强攻、吊球多点开花，打出一波连续得分高潮，最终以25:6的悬殊比分再下…"
