    "title": "石泰峰在学习贯彻习近平关于基层工作方法的重要论述座谈会上强调 学深悟透用好习近平关于基层工作方法的重要论述 坚持不懈大抓基层为民造福",
    "link": "https://www.chinanews.com.cn/gn/2026/09-18/10699248.shtml",
    "pub_date": "2026-09-18 21:58:02",
    "author": "",
    "description": "新华社北京9月18日电 学习贯彻习近平关于基层工作方法的重要论述座谈会18日在京召开。中共中央政治局委员、中央组织部部长石泰峰出席会议并讲话，强调要深入学习贯彻习近平新时代中国特色社会主义思想特别是习近平党建思想，学深悟透用好习近平关于基层工作方法的重要论述，坚定拥护“两个确立”、坚决做到“两个维护”，扎实做好新时代基层工作，不断巩固党的执政根基，夯实中国式现代化的基层基础。",
    "content": "新华社北京9月18日电 学习贯彻习近平关于基层工作方法的重要论述座谈会18日在京召开。中共中央政治局委员、中央组织部部长石泰峰出席会议并讲话，强调要深入学习贯彻习近平新时代中国特色社会主义思想特别是习近平党建思想，学深悟透用好习近平关于基层工作方法的重要论述，坚定拥护“两个确立”、坚决做到“两个维护”，扎实做好新时代基层工作，不断巩固党的执政根基，夯实中国式现代化的基层基础。"
