    "content": "新华社上海9月18日电（记者胡洁菲、赵逸赫）随着“出海”成为企业拓展新市场、融入全球产业链供应链的重要途径，围绕跨境数据流通等的数字出海服务正成为发展新课题。记者从上海市数据局获悉，自今年5月国家数据领域国际合作上海综合试点启动以来，已推出多项新服务。 按照国家数据领域国际合作上海综合试点实施方案，上海综合试点定位于构建立足上海、服务全国、辐射全球的企业“走出去”数字总通道。未来五年，上海将围绕6个部分17项具体试点任务，着力构建设施领先、规则互认、载体赋能、场景融合的国际数据合作新体系。 “数据领域的国际合作，基…"
