    "title": "日本核心CPI连续60个月同比上涨",
    "link": "http://www.news.cn/20260918/f053546e23de4097beb842b4a56b44ae/c.html",
    "pub_date": "2026-09-18 21:17:43",
    "author": "蓝建中,李诗萌",
    "description": "新华社东京9月18日电（记者蓝建中 李诗萌）日本总务省18日公布的数据显示，剔除生鲜食品后，日本8月核心消费价格指数（CPI）同比上涨1.7%，虽然涨幅较7月的1.8%有所收窄，但日本核心CPI已连续60个月同比上涨。 数据显示，8月能源价格同比下降0.7%，是核心CPI涨幅收窄的主要原因。其中，电费下降2.4%，城市燃气费下降0.8%，汽油价格下降2.6%。当月，剔除生鲜食品后的食品价格同比上涨2.7%。 三菱日联研究与咨询公司首席研…",
    "content": "新华社东京9月18日电（记者蓝建中 李诗萌）日本总务省18日公布的数据显示，剔除生鲜食品后，日本8月核心消费价格指数（CPI）同比上涨1.7%，虽然涨幅较7月的1.8%有所收窄，但日本核心CPI已连续60个月同比上涨。 数据显示，8月能源价格同比下降0.7%，是核心CPI涨幅收窄的主要原因。其中，电费下降2.4%，城市燃气费下降0.8%，汽油价格下降2.6%。当月，剔除生鲜食品后的食品价格同比上涨2.7%。 三菱日联研究与咨询公司首席研究员小林真一郎指出，8月核心CPI涨幅放缓，主要是受政府近期为电费、燃气费提供财…"
