    "description": "新华社北京9月18日电（记者刘慧、任军）中国证监会官网9月18日最新信息显示，贝莱德基金获批合格境内机构投资者（QDII）资格。贝莱德基金成为首家获得该项资格的新设外资公募基金公司，为进一步布局全球资产配置业务奠定基础。 QDII是境内投资者通过合格机构参与境外证券投资的重要渠道。此前，由合资转为外商独资的摩根基金、宏利基金和摩根士丹利基金均已取得QDII资格，获批时间均早于其成为外资独资公募的时间。贝莱德基金此次的“首家”，则限定于外…",
    "content": "新华社北京9月18日电（记者刘慧、任军）中国证监会官网9月18日最新信息显示，贝莱德基金获批合格境内机构投资者（QDII）资格。贝莱德基金成为首家获得该项资格的新设外资公募基金公司，为进一步布局全球资产配置业务奠定基础。 QDII是境内投资者通过合格机构参与境外证券投资的重要渠道。此前，由合资转为外商独资的摩根基金、宏利基金和摩根士丹利基金均已取得QDII资格，获批时间均早于其成为外资独资公募的时间。贝莱德基金此次的“首家”，则限定于外资在境内新设立的公募基金公司，体现了新设外资公募在跨境投资业务上的进一步拓展。 …"
