    "content": "新华社香港9月18日电 题：香港首个五年规划以顶层设计保障“一国两制”实践行稳致远 新华社记者刘欢 《香港特别行政区经济和社会发展第一个五年规划（2026-2030年）》16日正式公布。这是香港特区首次对经济和社会发展进行整体性的顶层设计，对于保障“一国两制”实践行稳致远具有里程碑意义。 香港首个五年规划的公布，适应新时代“一国两制”实践的新要求。当前，世界百年未有之大变局加速演进，中国已成为世界经济增长的主要稳定器和动力源。“十五五”规划勾勒了国家未来发展蓝图，并对香港更好融入和服务国家发展大局提出了更高要求，香…"
