    "content": "新华社北京9月18日电 为了加强未成年人网络保护，营造有利于未成年人身心健康的网络环境，保障未成年人合法权益，国家互联网信息办公室组织起草了《国务院关于保障未成年人健康安全使用网络的规定（征求意见稿）》，于18日向社会公开征求意见。意见反馈截止日期为2026年10月17日。 征求意见稿的制定立足我国未成年人网络保护治理实践，针对未成年人使用网络过程中出现的新情况新问题，创新制度设计，衔接有关法律法规；明确有关部门、网络服务提供者、智能终端产品制造者、应用程序分发平台服务提供者、群团组织、学校、监护人等各方主体在未成…"
