    "description": "新华社北京9月18日电 海湾国家沙特阿拉伯眼下面临也门胡塞武装日益猛烈的攻击，作为与沙特订立共同防务协议的盟友，巴基斯坦的反应备受外界关注。巴军方发言人17日接受媒体采访时表态称，巴方将“不惜一切”支持沙特，包括协助保卫沙特境内宗教圣地麦加和麦地那。 也门胡塞武装本周对沙特发动新一波袭击，沙特方面指认对方企图用无人机袭击麦加，遭沙特防空部队拦截并摧毁。伊斯兰合作组织秘书处随后发声谴责胡塞武装。胡塞武装方面否认袭击麦加，指责沙特“撒谎”。…",
