    "content": "泰国总理阿努廷17日出席中国驻泰国大使馆在曼谷诗丽吉王后国家会议中心举行的庆祝中华人民共和国成立77周年招待会，并代表泰国政府致辞。 阿努廷说，泰中是全面战略合作伙伴，应共同加强努力，应对地区和全球层面的挑战。他呼吁双方携手朝着构建更为稳定、更加繁荣、更可持续的泰中命运共同体的目标前行。 阿努廷在致辞后接受新华社记者采访时说，在中华人民共和国国庆来临之际，泰国人民向中国人民致以诚挚、美好的祝福。“祝愿大家身体健康、生活幸福，祝愿我们两国的友谊世代相传、历久弥坚。”（记者：常天童、万后德、耿凌楠；视频：史晨渲、李元昊…"
