    "content": "新华社昆明9月18日电（记者王贤思、严勇）云南西双版纳、红河等地国产榴莲陆续进入采摘期。部分果实经自然成熟后采摘，香气浓郁、甜度适宜，科研人员和种植企业围绕产量、品质等指标开展测产和品鉴。 云南西双版纳州景洪市勐罕镇的金枕榴莲种植基地。新华社发（刘洁摄） 9月16日，云南西双版纳州景洪市勐罕镇一处金枕榴莲种植基地里，首批“树上熟”金枕榴莲正式开采。科研团队现场测产数据显示，基地3至4年生榴莲树已逐步进入挂果期，5年生树实现稳定挂果，单株最高挂果34个，单果平均重3.7公斤，最重达8公斤，果实糖度超过36.9。 “从…"
