    "description": "新华社石家庄9月18日电（记者苏凯洋）入秋后，雄安新区暑气渐渐褪去。由启动区海岳大街向南拐进一条小路，在连片的树林和田野中行车约一公里，一座安静院落出现眼前——河北省文物考古研究院雄安新区文物保护与考古工作站。 记者见到“95后”考古队员倪萍时，她正和同事们梳理考古资料，一旁置物架摆放的鹰嘴锄、手铲等考古工具沾着未净的泥土。她们收养的流浪猫“福福”蜷在地面酣睡，为严谨的考古日常添了几分生活气息。 谈起在雄安的考古工作，倪萍格外兴奋：雄安…",
    "content": "新华社石家庄9月18日电（记者苏凯洋）入秋后，雄安新区暑气渐渐褪去。由启动区海岳大街向南拐进一条小路，在连片的树林和田野中行车约一公里，一座安静院落出现眼前——河北省文物考古研究院雄安新区文物保护与考古工作站。 记者见到“95后”考古队员倪萍时，她正和同事们梳理考古资料，一旁置物架摆放的鹰嘴锄、手铲等考古工具沾着未净的泥土。她们收养的流浪猫“福福”蜷在地面酣睡，为严谨的考古日常添了几分生活气息。 谈起在雄安的考古工作，倪萍格外兴奋：雄安新区被人们称作“未来之城”，其实它的历史一点也不平庸。 雄安新区设立后，有关部门…"
