    "content": "新华社武汉9月18日电（记者陈斌杰、闫睿、闫建华）如果没来到湖北京山，很难想象养牛大户和网球教练这两个迥异的身份会出现在同一个人身上。京山市温泉街道文峰村村民彭菊芳是资深网球爱好者。他在经营养殖业之余，还累计带出3000多名网球学员。 走入文峰村，随处可见网球元素。京山网球训练基地落户村内，村里拥有80多片球场，难能可贵的是，网球爱好者在这里不愁找不到“球搭子”。彭菊芳对记者说，京山网球氛围浓厚，这项运动走入了寻常百姓家。“我们村民放下锄头就能打球，不分年龄、不分职业、不分水平，人人都能拥抱这项运动。” 9月16日…"
