    "description": "新华社广州9月18日电 题：横琴粤澳深度合作区展现“琴澳和鸣”新气象 新华社记者肖思思、宋晨、王浩明 下午四点多，横琴口岸迎来一天中最密集的人流。喜茶横琴口岸门店里，店长马骞理把一杯少冰茶饮递给一位到横琴购物的澳门居民，“很多澳门居民常来光顾我们店，买一杯奶茶后再过关回到澳门”。 “两年多前刚开业时，口岸区域餐饮商家屈指可数。”马骞理回忆，短短几年，内地与澳门消费者往来穿梭，门店销量一路攀升到全国前列。 这家开在横琴口岸奶茶店的变化，正…",
    "content": "新华社广州9月18日电 题：横琴粤澳深度合作区展现“琴澳和鸣”新气象 新华社记者肖思思、宋晨、王浩明 下午四点多，横琴口岸迎来一天中最密集的人流。喜茶横琴口岸门店里，店长马骞理把一杯少冰茶饮递给一位到横琴购物的澳门居民，“很多澳门居民常来光顾我们店，买一杯奶茶后再过关回到澳门”。 “两年多前刚开业时，口岸区域餐饮商家屈指可数。”马骞理回忆，短短几年，内地与澳门消费者往来穿梭，门店销量一路攀升到全国前列。 这家开在横琴口岸奶茶店的变化，正是横琴粤澳深度合作区发展的小小侧影。 9月9日，旅客在位于横琴口岸的奶茶店里购买…"
