    "content": "新华社南昌9月18日电 江西省纪委监委18日通报，经江西省委批准，江西省纪委监委对江西省人大常委会原委员、省人大农业和农村委员会原副主任委员喻晓社严重违纪违法问题进行了立案审查调查。 经查，喻晓社身为党员领导干部，丧失理想信念，背弃初心使命，对组织不忠诚不老实，对抗组织审查；无视中央八项规定精神，长期违规接受宴请，违规借用管理服务对象住房和车辆；组织原则缺失，在组织函询时不如实说明问题，在干部选拔任用等工作中违规为他人谋取利益并收受财物；廉洁底线失守，违规收受礼品礼金，通过民间借贷获取大额回报，利用职权或职务上的影…"
