    "title": "俄外交部召见英国临时代办抗议英向乌克兰提供武器",
    "link": "http://www.news.cn/20260918/3421efa935534178834c7b874674cc0b/c.html",
    "pub_date": "2026-09-18 20:35:40",
    "author": "赵冰",
    "description": "新华社莫斯科9月18日电（记者赵冰）俄罗斯外交部18日在官方网站发表声明说，俄方当天召见英国驻俄临时代办达娜·多拉基亚，就英方不断向乌克兰提供无人机及其他武器装备提出抗议。 声明说，英国在乌克兰问题上采取的对抗立场显然意在延长和升级武装冲突，只会使政治解决前景更加遥远。俄方已向英方明确指出其一系列破坏行动所带来的风险。 声明强调，在俄军占据优势并在特别军事行动区域掌握战略主动权的背景下，英方的一系列做法是徒劳的。 声明还说，鉴于英方政策…",
    "content": "新华社莫斯科9月18日电（记者赵冰）俄罗斯外交部18日在官方网站发表声明说，俄方当天召见英国驻俄临时代办达娜·多拉基亚，就英方不断向乌克兰提供无人机及其他武器装备提出抗议。 声明说，英国在乌克兰问题上采取的对抗立场显然意在延长和升级武装冲突，只会使政治解决前景更加遥远。俄方已向英方明确指出其一系列破坏行动所带来的风险。 声明强调，在俄军占据优势并在特别军事行动区域掌握战略主动权的背景下，英方的一系列做法是徒劳的。 声明还说，鉴于英方政策，俄罗斯保留在行使自卫权框架内采取必要报复措施的权利。任何用于打击俄领土的英国在…"
