    "content": "36氪获悉，文化和旅游部印发《文化产业发展“十五五”规划》。其中提到，加快推动数字技术全方位全链条普及应用，壮大数字文化产业，发展以智能交互、沉浸体验为特征的新型文化业态。推动虚拟现实、高清显示、全息投影、智能穿戴等创新应用，发展数字动漫、数字演艺、数字娱乐、数字艺术、数字展览等新业态。推动内容、技术与空间融合，在文博、演艺、文旅融合等领域发展沉浸式新业态。创新发展时尚产业，培育一批彰显中国审美、中国风格的时尚产品和品牌。支持新能源、新材料在文化产业领域的创新应用，推动绿色低碳发展。支持量子科技、具身智能、脑机接口…"
