    "author": "刘芳洲",
    "description": "“今借到 段年明医生名下稻谷贰拾担正 还另收银圆捐献贰拾大圆 是实此据 经收人红三军战士李伟祥 廖运材 公元一九三四年十一月十二日”。 在湖南省郴州市苏仙区良田镇菜岭村村民段元法家中，至今保存着两张红军留下的字据，其中一张是借据。“这不是欠条，是红军和老百姓心连心的见证，我们永远不会拿去兑换。”段元法说。 借据中的段年明医生，是段元法的曾祖父，彼时是村里的郎中。 这是在段元法家中拍摄的两张红军字据。新华社发（卢经纬摄） 1934年11月…",
    "content": "“今借到 段年明医生名下稻谷贰拾担正 还另收银圆捐献贰拾大圆 是实此据 经收人红三军战士李伟祥 廖运材 公元一九三四年十一月十二日”。 在湖南省郴州市苏仙区良田镇菜岭村村民段元法家中，至今保存着两张红军留下的字据，其中一张是借据。“这不是欠条，是红军和老百姓心连心的见证，我们永远不会拿去兑换。”段元法说。 借据中的段年明医生，是段元法的曾祖父，彼时是村里的郎中。 这是在段元法家中拍摄的两张红军字据。新华社发（卢经纬摄） 1934年11月，中央红军长征正突破国民党军队设置在湖南郴县（今郴州市苏仙区、北湖区）良田至宜章…"
