    "content": "新华社西宁9月18日电（记者王浡、樊曦）记者从中铁十一局集团有限公司了解到，18日，随着最后一片长40米、重157吨的预制箱梁精准落位，同（仁）赛（尔龙）高速公路扎毛河特大桥顺利贯通，为全线建成通车奠定坚实基础。 同赛高速是国家高速公路网的重要组成部分，也是青海省高速公路网张掖至汶川高速公路的重要路段，线路全长204.52公里，采用双向4车道标准建设，山岭区设计时速80公里，平原区设计时速100公里。 扎毛河特大桥位于青海省黄南藏族自治州同仁市扎毛乡，地处青藏高原和黄土高原交界地带，平均海拔3100米，是全线重难点…"
