    "description": "新华社武汉9月18日电（记者龚联康）就网民反映的长江武汉段天兴洲附近水域有船只倾倒黑色泥状物有关问题，湖北省和武汉市联合调查组18日公布调查处理结果。经查，倾倒物为航道清淤疏浚产生的淤泥，属于“其他固体废物”，具有污染特性；抛泥区周边水域及下游取水点水质均符合地表水Ⅱ类标准；涉事企业因违法倾倒固体废物被立案查处，11名相关责任人被追责。 针对公众关注的环境影响问题，通报显示，调查组依据国家危险废物鉴别、固体废物鉴别等标准，对6个点位的水…",
    "content": "新华社武汉9月18日电（记者龚联康）就网民反映的长江武汉段天兴洲附近水域有船只倾倒黑色泥状物有关问题，湖北省和武汉市联合调查组18日公布调查处理结果。经查，倾倒物为航道清淤疏浚产生的淤泥，属于“其他固体废物”，具有污染特性；抛泥区周边水域及下游取水点水质均符合地表水Ⅱ类标准；涉事企业因违法倾倒固体废物被立案查处，11名相关责任人被追责。 针对公众关注的环境影响问题，通报显示，调查组依据国家危险废物鉴别、固体废物鉴别等标准，对6个点位的水下淤泥及驳船内黑色泥状物采样检测，结果显示重金属等指标均在标准浓度限值以下，不属…"
